@charset "UTF-8";
/* Modified from Carbon Design System: removed web fonts, unified font families, converted rem lengths to pixels, and replaced the built-in themes. */
html,
body,
div,
span,
applet,
object,
iframe,
h1,
h2,
h3,
h4,
h5,
h6,
p,
blockquote,
pre,
a,
abbr,
acronym,
address,
big,
cite,
code,
del,
dfn,
em,
img,
ins,
kbd,
q,
s,
samp,
small,
strike,
strong,
sub,
sup,
tt,
var,
b,
u,
i,
center,
dl,
dt,
dd,
ol,
ul,
li,
fieldset,
form,
label,
legend,
table,
caption,
tbody,
tfoot,
thead,
tr,
th,
td,
article,
aside,
canvas,
details,
embed,
figure,
figcaption,
footer,
header,
hgroup,
menu,
nav,
output,
ruby,
section,
summary,
time,
mark,
audio,
video {
  padding: 0;
  border: 0;
  margin: 0;
  font: inherit;
  font-feature-settings: "liga" 1;
  vertical-align: baseline;
}

sup {
  vertical-align: super;
}

sub {
  vertical-align: sub;
}

button,
select,
input,
textarea {
  border-radius: 0;
  font: inherit;
}

:where(code, kbd, samp, tt) {
  font-family: inherit;
}

label {
  font-size: var(--font-size-01);
}

:root {
  color-scheme: var(--mds-color-scheme, light);
  --radius-xs: 2px;
  --radius-sm: 4px;
  
  --card-title-lines: 2;
  --card-desc-lines: 3;
  --card-label-lines: 1;

  --spacing-01: 2px;
  --spacing-02: 4px;
  --spacing-03: 8px;
  --spacing-04: 12px;
  --spacing-05: 16px;
  --spacing-06: 24px;
  --spacing-07: 32px;
  --spacing-08: 40px;
  --spacing-09: 48px;
  --spacing-10: 64px;
  --spacing-11: 80px;
  --spacing-12: 96px;

  --size-01: 24px;
  --size-02: 32px;
  --size-03: 40px;
  --size-04: 48px;
  --size-05: 64px;
  --size-06: 80px;

  --font-size-01: 12px;
  --font-size-02: 14px;
  font-size: var(--font-size-02);

  --font-weight-01: 300;
  --font-weight-02: 400;
  --font-weight-03: 600;
  --font-family: "IBM Plex Sans", system-ui, sans-serif;
  font-family: var(--font-family);

  /* Typography shared across components and themes. */
  --line-height-01: 1.25;
  --line-height-02: 1.4;
  --line-height-03: 1.5;
  --letter-spacing-01: 0;
  --letter-spacing-02: 0.16px;
  --letter-spacing-03: 0.32px;
}

/* HTML5 display-role reset for older browsers */
article,
aside,
details,
figcaption,
figure,
footer,
header,
hgroup,
menu,
nav,
section {
  display: block;
}

body {
  background-color: var(--mds-background, #ffffff);
  color: var(--mds-text-primary, #161616);
  line-height: 1;
}

ol,
ul {
  list-style: none;
}

blockquote,
q {
  quotes: none;
}

blockquote::before,
blockquote::after,
q::before,
q::after {
  content: none;
}

table {
  border-collapse: collapse;
  border-spacing: 0;
}

html {
  box-sizing: border-box;
}

*,
*::before,
*::after {
  box-sizing: inherit;
}


body {
  font-weight: var(--font-weight-normal);
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}


strong {
  font-weight: var(--font-weight-semibold);
}

