.mds--css-grid {
  --mds-grid-gutter-start: calc(var(--mds-grid-gutter) / 2);
  --mds-grid-gutter-end: calc(var(--mds-grid-gutter) / 2);
  --mds-grid-column-hang: calc(var(--mds-grid-gutter) / 2);
  display: grid;
  box-sizing: border-box;
  grid-template-columns: repeat(var(--mds-grid-columns), minmax(0, 1fr));
  inline-size: 100%;
  margin-inline: auto;
  max-inline-size: 1584px;
  padding-inline: var(--mds-grid-margin);
}

.mds--css-grid--full-width {
  max-inline-size: 100%;
}

.mds--css-grid-column {
  --mds-grid-mode-start: var(--mds-grid-gutter-start);
  --mds-grid-mode-end: var(--mds-grid-gutter-end);
  margin-inline: var(--mds-grid-gutter-start) var(--mds-grid-gutter-end);
}
[dir=rtl] .mds--css-grid-column {
  margin-inline: var(--mds-grid-gutter-end) var(--mds-grid-gutter-start);
}

.mds--css-grid--narrow {
  --mds-grid-gutter-start: 0px; /* stylelint-disable-line length-zero-no-unit */
}

.mds--css-grid--condensed {
  --mds-grid-gutter: 1px;
  --mds-grid-column-hang: 15.5px;
}

.mds--css-grid--start {
  margin-inline-start: 0;
}

.mds--css-grid--end {
  margin-inline-end: 0;
}

.mds--subgrid {
  display: grid;
  grid-template-columns: repeat(var(--mds-grid-columns), minmax(0, 1fr));
  margin-inline: calc(var(--mds-grid-mode-start) * -1) calc(var(--mds-grid-mode-end) * -1);
}
[dir=rtl] .mds--subgrid {
  margin-inline: calc(var(--mds-grid-mode-end) * -1) calc(var(--mds-grid-mode-start) * -1);
}

.mds--subgrid--wide {
  --mds-grid-gutter-start: 16px;
  --mds-grid-gutter-end: 16px;
  --mds-grid-column-hang: 0;
}

.mds--subgrid--narrow {
  --mds-grid-gutter-start: 0px; /* stylelint-disable-line length-zero-no-unit */
  --mds-grid-gutter-end: 16px;
  --mds-grid-column-hang: 16px;
}

.mds--subgrid--condensed {
  --mds-grid-gutter: 1px;
  --mds-grid-gutter-start: 0.5px;
  --mds-grid-gutter-end: 0.5px;
  --mds-grid-column-hang: 15.5px;
}

.mds--grid-column-hang {
  margin-inline-start: var(--mds-grid-column-hang);
}
[dir=rtl] .mds--grid-column-hang {
  margin-inline: initial var(--mds-grid-column-hang);
}

